"""One-time, hash-verified release patch. Refuses unknown source versions."""
from pathlib import Path
import json
import hashlib

verification = json.loads(r'''[{"path":"package-lock.json","before":"8911fc50971c252853145aac5b656d11c3ced2de423f986b2417247c83d2644b","after":"34bd249f238e223157507edb0aaf742d63b04b884e1aa9888835ae24bd02f9ea","edits":[[2,3,"  \"version\": \"2.0.3\",\n"],[8,9,"      \"version\": \"2.0.3\",\n"]]},{"path":"package.json","before":"b1a20676a5e73a88c8bd26687ad3b9b65afe48f66b1c6dcd7097a9d24301d22e","after":"c69bc5ec713c789daf842ff2a1e1fb0c0d8b16103e4227d2f70d510325fdb14e","edits":[[2,3,"  \"version\": \"2.0.3\",\n"]]},{"path":"scripts/smoke-local.mjs","before":"b62f173eba590813d43c33953cb608f9c7b7dce9051565d1e6bedf5d8dbc00e5","after":"31b4c311cd41358708ecc4e8344b8cc71bd02845584f049c4b314ae10ab506de","edits":[[11,12,"const page = await fetch(`${BASE}/authorize?${q}`, { redirect: \"manual\" });\nif (page.status !== 200) throw new Error(`Consent page returned ${page.status}`);\nconst nonce = /name=\"consent\" value=\"([^\"]+)\"/.exec(await page.text())[1];\nconst auth = await fetch(`${BASE}/authorize`, { method: \"POST\", redirect: \"manual\", headers: { Origin: BASE, Cookie: page.headers.get(\"set-cookie\").split(\";\")[0] }, body: new URLSearchParams({ consent: nonce, decision: \"allow\" }) });\n"]]},{"path":"test/helpers/fake-d1.js","before":"ade70b8efe87186f760efe5625ab9f3f795c65949dc59c7c1d7e82122255697a","after":"3c114bedfbb9c1a4fbd3045481c41a20f953aa9674c9237bd2da4502c57e5608","edits":[[18,18,"          if (sql.startsWith(\"DELETE FROM oauth_store WHERE key=?\")) {\n            const [key, now] = args, row = rows.get(key);\n            if (!row || (row.expires_at !== null && row.expires_at <= now)) return null;\n            rows.delete(key); return { value: row.value };\n          }\n          if (sql.startsWith(\"UPDATE oauth_store SET value=json_set\")) {\n            const [family, key, now] = args, row = rows.get(key);\n            if (!row || row.expires_at <= now) return null;\n            const value = JSON.parse(row.value);\n            if (value.used) return null;\n            row.value = JSON.stringify({ ...value, used: 1, family });\n            return { value: row.value };\n          }\n"],[21,21,"          if (sql.startsWith(\"INSERT OR IGNORE INTO oauth_store\")) {\n            if (rows.has(args[0])) return { success: true, meta: { changes: 0 } };\n            rows.set(args[0], { value: args[1], expires_at: args[2] });\n            return { success: true, meta: { changes: 1 } };\n          }\n"]]},{"path":"test/mail.test.js","before":"f4549a7480f0aa6a89871af04e4739221974ecffcd059e526cfd8bfda078cd01","after":"464a4a8dce3a6c3deab3c5751c054c6e154b5fc7e32bb7a18f4399f257f8aaf1","edits":[[90,91,"  it(\"matches decoded Chinese body without a server TEXT index\", async () => {\n"],[92,94,"    expect(r.results.map(x => x.uid)).toEqual([101]);\n    expect(r.partial).toBe(false);\n    expect(imap.commands.some(c => /UID SEARCH.*CHARSET/.test(c))).toBe(false);\n"],[172,182,"  it(\"without UIDPLUS never EXPUNGEs or CLOSEs a whole folder\", async () => {\n"],[185,188,"    expect(r).toMatchObject({ moved: 1, move_method: \"copy\", source_expunged: false, pending_expunge: [102] });\n    expect(imap.folders.INBOX.messages.map(m => m.uid)).toEqual([101, 102]);\n"],[190,191,"    expect(imap.commands.some(c => / (EXPUNGE|CLOSE)$/.test(c))).toBe(false);\n    expect(imap.commands.some(c => c.includes(\"-FLAGS.SILENT\"))).toBe(false);\n"],[299,309,"  it(\"leaves a sent draft hidden and blocks duplicate sends without UIDPLUS\", async () => {\n"],[311,312,"    await call(\"save_draft\", { to: [\"ann@example.com\"], subject: \"SafePending\", body: \"x\" });\n"],[313,315,"    expect(r).toMatchObject({ sent: true, draft_removed: false, draft_hidden: true, source_expunged: false, pending_expunge: [1] });\n    expect(imap.folders.Drafts.messages).toHaveLength(1);\n    expect(imap.commands.some(c => / (EXPUNGE|CLOSE)$/.test(c))).toBe(false);\n    expect((await call(\"send_draft\", { uid: 1 })).error).toMatch(/already sent/);\n    expect(smtp.sent).toHaveLength(1);\n"],[324,325,"    expect(r.draft_removed).toBe(false); // Physical deletion is not falsely claimed.\n"]]},{"path":"test/oauth.test.js","before":"c3f9b80cd98293b908c4fcb62a490aeafc88c3f2daef75e09312622a0dae23e6","after":"d6ad4e6d9e6d595fedfb02fe57f50793254a1c52bd185a13ee7fde574de2636f","edits":[[138,139,"    const deps = { verifyAccess: async () => ({ ok: true, email: \"owner@example.com\" }) };\n    const page = await route(new Request(`${ORIGIN}/authorize?${q}`), e, deps);\n    expect(page.status).toBe(200);\n    const nonce = /name=\"consent\" value=\"([^\"]+)\"/.exec(await page.text())[1];\n    const auth = await route(new Request(`${ORIGIN}/authorize`, { method: \"POST\", headers: { Origin: ORIGIN, Cookie: page.headers.get(\"Set-Cookie\").split(\";\")[0] }, body: new URLSearchParams({ consent: nonce, decision: \"allow\" }) }), e, deps);\n"],[155,156,"    expect(init.result.serverInfo).toMatchObject({ name: \"qqmail-mcp\", version: \"2.0.3\" });\n"]]},{"path":"wrangler.jsonc","before":"5546bfe0a1e94e0ff981b0c036ddf8371ceb984a42a3839d1e05cfd6bd158773","after":"ba9be5c48b74f13e86ac31521b23342ba13f990900de9f88435bfce46d113179","edits":[[14,14,"  \"observability\": { \"enabled\": true, \"head_sampling_rate\": 1, \"logs\": { \"enabled\": true, \"invocation_logs\": false } },\n"]]}]''')
patches = json.loads(Path('scripts/runtime-2.0.3.json').read_text()) + verification
for patch in patches:
    path = Path(patch['path'])
    assert not path.is_absolute() and '..' not in path.parts
    original = path.read_text() if path.exists() else ''
    digest = hashlib.sha256(original.encode()).hexdigest()
    if digest == patch['after']:
        continue
    assert digest == patch['before'], f'Unexpected source revision: {path}'
    lines = original.splitlines(keepends=True)
    for start, end, replacement in reversed(patch['edits']):
        lines[start:end] = [replacement]
    updated = ''.join(lines)
    assert hashlib.sha256(updated.encode()).hexdigest() == patch['after'], f'Patch integrity failed: {path}'
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(updated)
    print(f'Applied and SHA256 verified: {path}')
